// Import the Verus prelude so that `requires`, `ensures`, and `forall` are in scope.
use verus::prelude::*;

#[ensures(
    // `t` is the input vector and `result` is the returned vector.
    // We ensure (1) they have the same length
    //         (2) at each index `i < t.len()`, the characters agree.
    |t: Vec<char>, result: Vec<char>| 
        result.len() == t.len() &&
        forall(|i: usize| i < t.len() ==> result[i] == t[i])
)]
fn solve(t: Vec<char>) -> Vec<char> {
    // Pre‐allocate a new vector with the same capacity as the input.
    let mut result = Vec::with_capacity(t.len());
    
    // Traverse the input from start to end, appending each character.
    for c in t {
        result.push(c);
    }
    
    // Return the newly constructed vector, which has the same length
    // and contents as the input.
    result
}

